'use strict';
const people=window.PEOPLE, byId=Object.fromEntries(people.map(p=>[p.id,p]));
const $=s=>document.querySelector(s), genNames=['家族之外','第一代','第二代','第三代','第四代','第五代','第六代','第七代'];
const generationNarratives=[null, {"title": "马孔多的创建与家族的奠基", "description": "创始人的探索，以及乌尔苏拉对家庭的经营。"}, {"title": "战争、激情与理想的幻灭", "description": "上校的战争经历，长子的冒险，以及阿玛兰妲的情感纠葛。"}, {"title": "权力的失控与禁忌的爱情", "description": "阿尔卡蒂奥的暴政、奥雷里亚诺·何塞的姑侄恋情。"}, {"title": "繁荣的顶点与历史的创伤", "description": "财富与宴饮、香蕉公司与大屠杀，以及记忆被抹除。"}, {"title": "家族的离散与重建的愿望", "description": "子女远行、梅梅被迫离家，以及阿玛兰妲·乌尔苏拉归来后重振老宅的努力。"}, {"title": "身世的追索与命运的破译", "description": "奥雷里亚诺·巴比伦逐渐认识自己的身世，并读懂羊皮卷。"}, {"title": "预言的应验与家族的终结", "description": "最后一个孩子的出生与死亡，使家族走向终点。"}];
const pos={
 'jose-founder':[700,1],ursula:[940,1],rebeca:[150,2],'jose-son':[370,2],pilar:[590,2],'aureliano-colonel':[810,2],'remedios-moscote':[1030,2],amaranta:[1250,2],pietro:[1470,2],
 arcadio:[390,3],'santa-sofia':[630,3],'aureliano-jose':[950,3],'seventeen-sons':[1230,3],
 'remedios-beauty':[220,4],'jose-second':[460,4],petra:[700,4],'aureliano-second':[940,4],fernanda:[1180,4],
 'jose-younger':[200,5],meme:[440,5],mauricio:[680,5],'amaranta-ursula':[1100,5],gaston:[1340,5],
 'aureliano-babilonia':[680,6],'last-aureliano':[940,7]
};
const xy=id=>({x:pos[id][0],y:55+(pos[id][1]-1)*310});
let zoom=.7,view=innerWidth<640?'list':'tree',generation=1,activePerson=null,lastFocus=null;
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function portrait(p){return p.id==='seventeen-sons'?'<span class="portrait group-portrait" aria-label="十七子集体档案">17</span>':`<img class="portrait" src="${p.imageData||`assets/${p.id}.jpg`}" alt="${esc(p.name)}的艺术肖像" loading="lazy" width="82" height="82">`;}
function listCard(p){return `<button class="list-card" data-person="${p.id}">${portrait(p)}<div><h3>${esc(p.name)}</h3><p>${genNames[p.generation]} · ${esc(p.role)}</p></div><span class="arrow" aria-hidden="true">↗</span></button>`;}
function renderTree(){
 let cards='';for(let g=1;g<=7;g++)cards+=`<div class="gen-marker" style="top:${55+(g-1)*310}px">${genNames[g]}<small>GENERATION 0${g}</small><span class="gen-theme">${generationNarratives[g].title}</span></div>`;
 for(const p of people.filter(p=>pos[p.id])){const {x,y}=xy(p.id);cards+=`<button class="person-card" data-person="${p.id}" style="left:${x}px;top:${y}px"><span class="index">0${p.generation}</span>${portrait(p)}<span class="name">${esc(p.name)}</span><span class="role">${esc(p.role)}</span></button>`;}
 $('#cards').innerHTML=cards;
 let edges='',edgePeople='';const path=(d,cl='blood')=>edges+=`<path d="${d}" class="${cl}" data-related="${edgePeople}"/>`;
 const grouped={};for(const p of people.filter(p=>pos[p.id]&&p.parents.length)){const key=[...p.parents].sort().join('|');(grouped[key]??=[]).push(p.id);}
 const lanes={};for(const [key,children]of Object.entries(grouped)){edgePeople=key+'|'+children.join('|');const parents=key.split('|').filter(id=>pos[id]);const parentPts=parents.map(xy);const childPts=children.map(xy);if(parents.includes('amaranta-ursula')){const a=xy('amaranta-ursula'),b=xy('aureliano-babilonia'),c=xy('last-aureliano');path(`M${a.x+158} ${a.y+155} H1660 V${c.y-40} H${c.x+79} V${c.y}`);path(`M${b.x+79} ${b.y+202} V${c.y-40} H${c.x+79}`);continue;}
 const bottom=Math.max(...parentPts.map(p=>p.y+202)),lane=(lanes[bottom]=(lanes[bottom]||0)+1),forkY=bottom+30+lane*18,center=parentPts.reduce((n,p)=>n+p.x+79,0)/parentPts.length,joinY=bottom+8+lane*14;
 for(const p of parentPts)path(`M${p.x+79} ${p.y+202} V${joinY} H${center}`);
 path(`M${center} ${joinY} V${forkY}`);edges+=`<circle cx="${center}" cy="${joinY}" r="3" fill="#9aa78c" data-related="${edgePeople}"/>`;
 for(const c of childPts)path(`M${center} ${forkY} H${c.x+79} V${c.y}`);
 }
 const seen=new Set;for(const p of people.filter(p=>pos[p.id]))for(const id of p.partners.filter(id=>pos[id])){const key=[p.id,id].sort().join('|');if(seen.has(key))continue;seen.add(key);edgePeople=key;const a=xy(p.id),b=xy(id);if(a.y!==b.y){path(`M${a.x+158} ${a.y+110} H1610 V${b.y+110} H${b.x+158}`,'partner');continue;}const l=a.x<b.x?a:b,r=a.x<b.x?b:a;if(r.x-l.x<260){path(`M${l.x+158} ${l.y+102} H${r.x}`,'partner');}else{const lane=p.id==='pietro'||id==='pietro'?12:27;path(`M${l.x+79} ${l.y} V${l.y-lane} H${r.x+79} V${r.y}`,'partner');}}
 edgePeople='jose-founder|ursula|rebeca';const f=xy('jose-founder'),u=xy('ursula'),r=xy('rebeca');path(`M${f.x+79} ${f.y+202} V${f.y+280} H${r.x+50} V${r.y}`,'adoptive');
 $('#edges').innerHTML=edges;
}
function setZoom(z){zoom=Math.max(.32,Math.min(1.25,z));$('#graph').style.transform=`scale(${zoom})`;$('#graphSizer').style.width=`${1770*zoom}px`;$('#graphSizer').style.height=`${2260*zoom}px`;$('#zoomLabel').textContent=`${Math.round(zoom*100)}%`;}
function fit(){setZoom(Math.max(.32,Math.min(1,($('#graphViewport').clientWidth-20)/1770)));}
function setView(v){view=v;$('#treeView').hidden=v!=='tree';$('#listView').hidden=v!=='list';$('#treeBtn').setAttribute('aria-pressed',v==='tree');$('#listBtn').setAttribute('aria-pressed',v==='list');if(v==='tree')requestAnimationFrame(fit);}
function renderList(){ $('#generationNarrative').innerHTML=`<span class="eyebrow">${genNames[generation]} · 主要叙事</span><h3>${generationNarratives[generation].title}</h3><p>${generationNarratives[generation].description}</p>`; $('#generationTabs').innerHTML=genNames.slice(1).map((name,i)=>`<button data-gen="${i+1}" class="${generation===i+1?'active':''}" aria-current="${generation===i+1?'true':'false'}">${name}</button>`).join('');$('#generationList').innerHTML=people.filter(p=>p.generation===generation).map(listCard).join('');}
function relationRows(p){let rows=[];const add=(label,ids)=>{if(ids.length)rows.push(`<div class="relation"><span>${label}</span><div>${ids.map(id=>`<button data-person="${id}">${esc(byId[id].name)}</button>`).join(' · ')}</div></div>`);};add('父母',p.parents);add('养父母',p.adoptiveParents||[]);add('伴侣',p.partners);add('子女',people.filter(x=>x.parents.includes(p.id)).map(x=>x.id));add('收养',people.filter(x=>(x.adoptiveParents||[]).includes(p.id)).map(x=>x.id));add('手足',people.filter(x=>x.id!==p.id&&p.parents.some(id=>x.parents.includes(id))).map(x=>x.id));return rows.join('')||'<p>这位人物没有在图中列出的亲生子女或伴侣。</p>';}
function openPerson(id){const p=byId[id];if(!p)return;activePerson=id;$('#personContent').innerHTML=`<div class="profile-head">${portrait(p)}<div class="eyebrow">${genNames[p.generation]} / ${esc(p.role)}</div><h2 id="personName">${esc(p.name)}</h2><p class="spanish">${esc(p.spanish)}</p><div>${p.traits.map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div></div><div class="profile-body"><h3>人物小传</h3><p>${esc(p.intro)}</p>${p.namedMembers?.length?`<h3>书中具名的五位儿子</h3><ul class="named-members">${p.namedMembers.map(n=>`<li><strong>${esc(n.name)}</strong><br><span class="art-note">${esc(n.spanish)}</span><p>${esc(n.intro)}</p></li>`).join("")}</ul><p class="art-note">原文核对：${p.sources.map(s=>`<a href="${esc(s.url)}" target="_blank" rel="noopener">${esc(s.label)}</a>`).join(" · ")}</p>`:""}<h3>家族关系</h3><div class="relations">${relationRows(p)}</div><p class="art-note">伴侣一栏含婚姻、情人及订婚关系，具体见小传。代际按家族血缘标记。</p><h3>经历与结局</h3><p>${esc(p.spoiler)}</p><h3>肖像创作说明</h3><p class="art-note">${esc(p.appearance)}</p></div>`;if(!$('#personDialog').open){lastFocus=document.activeElement;$('#personDialog').showModal();}$('#personDialog').scrollTop=0;$('#closeDialog').focus();}
const normalize=s=>s.toLowerCase().normalize('NFD').replace(/[\u0300-\u036f\s·.（）()]/g,'');
function search(){const q=normalize($('#search').value.trim());$('#searchCount').textContent='';if(!q){$('#searchResults').hidden=true;setView(view);return;}const found=people.filter(p=>normalize(p.name+p.spanish+p.role+p.traits.join(' ')+(p.namedMembers||[]).map(n=>n.name+n.spanish).join(' ')).includes(q));$('#searchCount').textContent=`${found.length} 项`;$('#searchResults').hidden=false;$('#treeView').hidden=true;$('#listView').hidden=true;$('#searchResults').innerHTML=found.length?found.map(listCard).join(''):'<p class="empty">没有找到这个名字，试试“奥雷里亚诺”或“创始人”。</p>';}
document.addEventListener('click',e=>{const person=e.target.closest('[data-person]');if(person)openPerson(person.dataset.person);const gen=e.target.closest('[data-gen]');if(gen){generation=Number(gen.dataset.gen);renderList();}});
$('#treeBtn').onclick=()=>{$('#search').value='';$('#searchResults').hidden=true;$('#searchCount').textContent='';setView('tree');};$('#listBtn').onclick=()=>{$('#search').value='';$('#searchResults').hidden=true;$('#searchCount').textContent='';setView('list');};$('#zoomIn').onclick=()=>setZoom(zoom+.1);$('#zoomOut').onclick=()=>setZoom(zoom-.1);$('#fit').onclick=fit;$('#search').addEventListener('input',search);$('#closeDialog').onclick=()=>$('#personDialog').close();$('#personDialog').addEventListener('close',()=>{activePerson=null;lastFocus?.focus();});$('#closeAbout').onclick=()=>$('#aboutDialog').close();$('#aboutBtn').onclick=$('#sourcesBtn').onclick=()=>$('#aboutDialog').showModal();for(const d of document.querySelectorAll('dialog'))d.addEventListener('click',e=>{if(e.target===d){const r=d.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)d.close();}});
$('#companionCards').innerHTML=people.filter(p=>p.generation===0).map(listCard).join('');renderTree();renderList();setView(view);setZoom(.7);if(view==='tree')requestAnimationFrame(fit);

function highlight(id){document.querySelectorAll('#edges path,#edges circle').forEach(e=>{const match=e.dataset.related.split('|').includes(id);e.style.opacity=id?(match?'1':'.15'):'1';e.style.strokeWidth=id&&match?'3':'1.6';});}
$('#cards').addEventListener('pointerover',e=>{const c=e.target.closest('[data-person]');if(c)highlight(c.dataset.person);});$('#cards').addEventListener('pointerout',()=>highlight(null));$('#cards').addEventListener('focusin',e=>{const c=e.target.closest('[data-person]');if(c)highlight(c.dataset.person);});$('#cards').addEventListener('focusout',()=>highlight(null));
